import assert from 'node:assert/strict';
await import('./test/setup.ts');
const { createPublicKnowledgeSearch } = await import('./src/knowledge/public-search.ts');
const { projectPrivateToolResult, PRIVATE_TOOL_RESULT_MAX_BYTES } = await import('./src/engine/private-tool-results.ts');
const text = '文'.repeat(4096);
const crossref = JSON.stringify({ status: 'ok', message: { items: Array.from({ length: 5 }, (_, index) => ({ DOI: `10.1234/unicode${index}`, title: [text], publisher: '版'.repeat(1024), type: '類'.repeat(128) })) } });
const wikidata = JSON.stringify({ success: 1, search: Array.from({ length: 5 }, (_, index) => ({ id: `Q${1000 + index}`, label: text, description: text })) });
const bodies = { crossref: Buffer.byteLength(crossref), wikidata: Buffer.byteLength(wikidata) };
assert(Object.values(bodies).every(bytes => bytes < 524288));
let requests = 0;
const search = createPublicKnowledgeSearch({ fetch: async url => { requests++; return new Response(new URL(String(url)).hostname === 'api.crossref.org' ? crossref : wikidata, { headers: { 'content-type': 'application/json' } }); } });
const result = await search({ query: 'test Unicode valide', sources: ['crossref', 'wikidata'], limit: 5, language: 'fr' }, 'live');
assert.equal(result.status, 'complete'); assert.equal(result.ok, true); assert.equal(result.results.length, 10); assert.equal(requests, 2);
const projected = projectPrivateToolResult('knowledge_search', result);
assert(projected); assert.equal(projected.status, 'complete'); assert.equal(projected.sources.length, 10); assert.equal(projected.details.metadata_truncated, true);
assert(Buffer.byteLength(JSON.stringify(projected)) <= PRIVATE_TOOL_RESULT_MAX_BYTES - 4096);
console.log(JSON.stringify({ body_bytes: bodies, tool_status: result.status, tool_results: result.results.length, raw_result_bytes: Buffer.byteLength(JSON.stringify(result)), projected_bytes: Buffer.byteLength(JSON.stringify(projected)), retained_sources: projected.sources.length, metadata_truncated: projected.details.metadata_truncated, calls: requests, external_calls: 0 }, null, 2));
